"O português é o idioma de origem. Em inglês e espanhol já estão traduzidos o código, o ecrã bloqueado, as datas e o assistente inicial; as apps ainda aparecem em português.": "Португальский является исходным языком. На английском и испанском уже переведены код-пароль, экран блокировки, даты и ассистент настройки; приложения пока отображаются на португальском.",
"Outros idiomas (tradução parcial)": "Другие языки (частичный перевод)",
"Nestes idiomas só parte do assistente inicial, o código e as datas estão traduzidos.": "На этих языках переведена только часть ассистента настройки, код-пароль и даты.",
"Data e hora": "Дата и время",
"Data e Hora": "Дата и время",
"Formato 24 horas": "24-часовой формат",
"Fonte da hora": "Источник времени",
"Relógio do computador": "Часы компьютера",
"A hora da barra de estado vem do relógio do teu computador. O modo escuro automático segue a hora do jogo.": "Время в строке состояния берётся с часов вашего компьютера. Автоматический тёмный режим следует за игровым временем.",
"O teclado no ecrã aparece ao tocar num campo de texto. Podes escrever também com o teclado físico.": "Экранная клавиатура появляется при нажатии на текстовое поле. Также можно печатать на физической клавиатуре.",
"Teclado no ecrã": "Экранная клавиатура",
"Repor todas as definições mantém a conta, contactos e mensagens.": "Сброс всех настроек сохраняет учётную запись, контакты и сообщения.",
