"Automático: escuro entre as 20h e as 7h (hora do jogo).": "Автоматически: тёмное с 20:00 до 07:00 (игровое время).",
"Brilho": "Яркость",
"Transparente": "Прозрачный",
"Tingido": "Тонированный",
"Ajusta a transparência do vidro em barras, botões, Centro de controlo, notificações e ecrã bloqueado. No meio fica como o PearOS de fábrica.": "Настраивает прозрачность стекла в панелях, кнопках, Пункте управления, уведомлениях и на экране блокировки. В середине всё выглядит как в стандартной PearOS.",
"Tamanho do texto": "Размер текста",
"Pequeno": "Мелкий",
"Normal": "Обычный",
"Grande": "Крупный",
"Night Shift": "Night Shift",
"Tinge o ecrã de âmbar, mais confortável à noite.": "Окрашивает экран в янтарный цвет, так комфортнее ночью.",
"Movimento e hora": "Движение и время",
"Reduzir movimento": "Уменьшить движение",
"Reduzir movimento: as apps e os menus aparecem por desvanecimento, sem crescer do ícone nem efeito de mola. Desligar as 24 horas mostra \"9:41\" em vez de \"09:41\".": "Уменьшить движение: приложения и меню появляются плавным проявлением, без увеличения из значка и пружинного эффекта. Если выключить 24-часовой формат, вместо «09:41» будет «9:41».",
"Bloqueio automático": "Автоблокировка",
"30 segundos": "30 секунд",
