"10 minutos": "10 минут",
"Bloquear ao fechar o telemóvel": "Блокировать при закрытии телефона",
"Etiquetas dos ícones": "Подписи значков",
"O bloqueio automático também conta com uma app aberta; uma chamada em curso e a câmara mantêm o ecrã aceso.": "Автоблокировка считает время и при открытом приложении; текущий вызов и камера не дают экрану погаснуть.",
"Tamanho do telemóvel no ecrã": "Размер телефона на экране",
"Só no jogo. Pequeno ocupa menos espaço.": "Только в игре. Маленький занимает меньше места.",
"Cor de destaque": "Цвет акцента",
"Cor do sistema": "Цвет системы",
"A cor aplica-se a botões, ligações, seleções, widgets, Centro de controlo e ecrã bloqueado.": "Цвет применяется к кнопкам, ссылкам, выделению, виджетам, Пункту управления и экрану блокировки.",
"Interruptores com a cor de destaque": "Переключатели в цвете акцента",
"Cor personalizada (hex)": "Свой цвет (hex)",
"Fundos": "Обои",
"Fundo": "Обои",
