"Usar este fundo": "Использовать эти обои",
"Fundo aplicado": "Обои применены",
"Personalizar": "Настроить",
"Fundo definido no ecrã bloqueado e no principal": "Обои установлены на экран блокировки и главный экран",
"Um fundo novo aplica-se ao ecrã bloqueado e ao ecrã principal. Em Personalizar podes mudar cada um: cor, gradiente, uma foto ou desfocar o ecrã principal.": "Новые обои применяются к экрану блокировки и к главному экрану. В разделе «Настроить» можно изменить каждый: цвет, градиент, фото или размытие главного экрана.",
"Também podes manter pressionado o ecrã bloqueado para ver e trocar todos os fundos.": "Также можно нажать и удерживать экран блокировки, чтобы увидеть все обои и переключиться между ними.",
"A personalização de fundos não está disponível.": "Настройка обоев недоступна.",
"Personalizar ecrã bloqueado": "Настроить экран блокировки",
"Ou mantém pressionado o ecrã bloqueado.": "Или нажмите и удерживайте экран блокировки.",
"Compacto (PearOS 27): a hora fica pequena ao lado da data e dos widgets, no topo, e o fundo aparece inteiro.": "Компактный (PearOS 27): время уменьшается и стоит рядом с датой и виджетами вверху, а обои видны целиком.",
"Relógio compacto": "Компактные часы",
