"Always-On Display": "Always-On Display",
"Desligado, o botão lateral apaga mesmo o ecrã. Ligado, mantém a hora esbatida sobre o fundo escurecido.": "Если выключено, боковая кнопка полностью гасит экран. Если включено, приглушённое время остаётся поверх затемнённых обоев.",
"Sempre ligado": "Всегда включён",
"Widgets (máx. 3)": "Виджеты (макс. 3)",
"Notificações no ecrã bloqueado": "Уведомления на экране блокировки",
"Por app": "По приложениям",
"Em Notificações escolhes, app a app, se aparecem no ecrã bloqueado e se mostram o conteúdo.": "В разделе «Уведомления» вы выбираете для каждого приложения, показывать ли его на экране блокировки и показывать ли содержимое.",
"Sons e háptica": "Звуки и тактильные сигналы",
"Volume geral": "Общая громкость",
"Toque e chamadas": "Рингтон и вызовы",
"Sons do sistema": "Системные звуки",
"Som das notificações": "Звук уведомлений",
"Toques": "Рингтоны",
"Toque": "Рингтон",
"Permitir notificações": "Допуск уведомлений",
"%s não mostra notificações, nem no centro de notificações.": "%s не показывает уведомления, даже в Центре уведомлений.",
"Sem banners, a notificação entra só no centro de notificações (o som segue o interruptor Sons). Sem Ecrã bloqueado, não aparece no ecrã bloqueado.": "Без баннеров уведомление попадает только в Центр уведомлений (звук зависит от переключателя «Звуки»). Без экрана блокировки оно не появляется на экране блокировки.",
"Emblemas: o número vermelho no ícone da app no ecrã principal.": "Значки: красное число на значке приложения на главном экране.",
"Aparência no ecrã bloqueado": "Вид на экране блокировки",
"Pré-visualizações": "Показ миниатюр",
"Nunca: o cartão mostra só o nome da app, sem o texto. Quando desbloqueado: o texto só aparece com o telemóvel desbloqueado.": "Никогда: на карточке только название приложения, без текста. Когда разблокирован: текст виден, только когда телефон разблокирован.",
"Nunca: o cartão mostra só o nome da app, sem o texto. Quando desbloqueado: o texto só aparece com o PearPhone desbloqueado.": "Никогда: на карточке только название приложения, без текста. Когда разблокирован: текст виден, только когда PearPhone разблокирован.",
"Nenhuma app mostra notificações. As chamadas continuam a tocar.": "Ни одно приложение не показывает уведомления. Вызовы по-прежнему звонят.",
"Não incomodar": "Не беспокоить",
"Ligado": "Вкл.",
"Varia por app": "Зависит от приложения",
