"Foco": "Фокус",
"Dormir": "Сон",
"Só um modo de cada vez. Com qualquer modo ligado as notificações ficam silenciosas e sem avisos flutuantes, como no \"Não incomodar\"; Trabalho e Dormir ainda não têm listas de apps permitidas.": "Только один режим за раз. При любом включённом режиме уведомления беззвучны и без всплывающих сообщений, как в режиме «Не беспокоить»; у режимов «Работа» и «Сон» пока нет списков разрешённых приложений.",
"Só um foco de cada vez. Com qualquer foco ligado as notificações ficam silenciosas e sem banners, como no \"Não incomodar\"; Trabalho e Dormir ainda não têm listas de apps permitidas.": "Только один фокус за раз. При любом включённом фокусе уведомления беззвучны и без баннеров, как в режиме «Не беспокоить»; у фокусов «Работа» и «Сон» пока нет списков разрешённых приложений.",
"Centro de controlo": "Пункт управления",
"Controlos incluídos": "Включённые элементы",
"Ativa ou desativa atalhos. A ordem segue a ordem desta lista.": "Включайте или отключайте ярлыки. Порядок соответствует порядку в этом списке.",
"Abrir Centro de controlo": "Открыть Пункт управления",
"Autorização revogada": "Разрешение отозвано",
"Apps externas: autorizações no servidor": "Внешние приложения: разрешения на сервере",
"O que o servidor aceita que cada app externa faça em teu nome. \"Uma vez\" termina quando a app é fechada nas apps recentes ou quando sais.": "Что сервер позволяет каждому внешнему приложению делать от вашего имени. «Один раз» заканчивается, когда приложение закрыто в недавних приложениях или когда вы выходите.",
"O que o servidor aceita que cada app externa faça em teu nome. \"Uma vez\" termina quando a app é fechada no alternador ou quando sais.": "Что сервер позволяет каждому внешнему приложению делать от вашего имени. «Один раз» заканчивается, когда приложение закрыто в переключателе приложений или когда вы выходите.",
"%s · uma vez": "%s · один раз",
"Serviços de localização": "Службы геолокации",
"Apps que pediram acesso": "Приложения, запросившие доступ",
"Com os serviços de localização desligados nenhuma app recebe a tua posição, mesmo as que têm acesso.": "Если службы геолокации выключены, ни одно приложение не получает ваше местоположение, даже те, у которых есть доступ.",
"\"Permitido uma vez\" dura até a app ser fechada nas apps recentes.": "«Разрешено один раз» действует, пока приложение не будет закрыто в недавних приложениях.",
"\"Permitido uma vez\" dura até a app ser fechada no alternador.": "«Разрешено один раз» действует, пока приложение не будет закрыто в переключателе приложений.",
"Permitido uma vez": "Разрешено один раз",
"Nenhuma app pediu acesso ainda.": "Ни одно приложение пока не запрашивало доступ.",
"Ativado": "Включено",
"Desativado": "Выключено",
"Privacidade e segurança": "Конфиденциальность и безопасность",
"Relatório de privacidade": "Отчёт о конфиденциальности",
"Mensagens e chamadas": "Сообщения и вызовы",
"Recibos de leitura: desligados, quem te escreve deixa de ver \"Lida\" nas conversas contigo e tu também deixas de o ver nas tuas. Nos grupos as tuas leituras continuam a contar para quem enviou. Visto por último e online: desligado, ninguém vê se estás online nem quando estiveste pela última vez.": "Уведомления о прочтении: если выключены, те, кто вам пишет, больше не видят «Прочитано» в переписке с вами, и вы тоже не видите этого в своей. В группах ваши прочтения по-прежнему учитываются для отправителя. Был(а) в сети и онлайн: если выключено, никто не видит, находитесь ли вы онлайн и когда были в сети в последний раз.",
"Enviar recibos de leitura": "Отправлять уведомления о прочтении",
