"Sem código, deslizar para cima no ecrã bloqueado abre o telemóvel. Ativa um código para o proteger e usar o Face Key.": "Без кода-пароля смахивание вверх на экране блокировки открывает телефон. Включите код-пароль, чтобы защитить его и использовать Face Key.",
