"Nesta versão a bateria não descarrega nem carrega: o nível é fixo. O modo de poupança só pinta o ícone da bateria de amarelo.": "В этой версии батарея не разряжается и не заряжается: уровень зафиксирован. Режим энергосбережения лишь окрашивает значок батареи в жёлтый цвет.",
