"Compra e vende veículos, casas e mais. Carros, casas e tudo o resto, num toque.": "Покупай и продавай транспорт, дома и многое другое. Машины, дома и всё остальное в одно касание.",
"Conhece pessoas em Los Santos. Desliza, combina, conversa.": "Знакомься с людьми в Los Santos. Свайпай, находи пару, общайся.",
"Pede polícia, EMS, mecânico, táxi e mais. Pede ajuda com a tua localização.": "Вызывай полицию, скорую, механика, такси и не только. Проси помощи с отправкой геопозиции.",
"O clássico. Come, cresce e não te mordas. A cada cinco frutas fica mais rápido, e podes jogar com ou sem paredes. O clássico. Come, cresce e não te mordas. A cada cinco frutas fica mais rápido, e podes jogar com ou sem paredes.": "Классика. Ешь, расти и не кусай себя. Каждые пять фруктов скорость растёт, а играть можно со стенами или без. Классика. Ешь, расти и не кусай себя. Каждые пять фруктов скорость растёт, а играть можно со стенами или без.",
"Parte todos os tijolos sem deixar cair a bola. Tem tijolos resistentes, bónus que caem e níveis sem fim. Parte todos os tijolos sem deixar cair a bola. Tem tijolos resistentes, bónus que caem e níveis sem fim.": "Разбей все кирпичи, не уронив мяч. Есть прочные кирпичи, падающие бонусы и бесконечные уровни. Разбей все кирпичи, не уронив мяч. Есть прочные кирпичи, падающие бонусы и бесконечные уровни.",
"Os teus veículos, localização e garagem. Localiza, favorita, dá alcunhas.": "Твой транспорт, его местоположение и гараж. Находи, добавляй в избранное, давай прозвища.",
"Salas anónimas por alcunha. As mensagens ficam guardadas no servidor. Por alcunha. As mensagens ficam no servidor.": "Анонимные комнаты по прозвищу. Сообщения хранятся на сервере. По прозвищу. Сообщения остаются на сервере.",
"Descobre o campo sem tocar numa mina. Três dificuldades, modo bandeira e abertura automática à volta dos números. Descobre o campo sem tocar numa mina. Três dificuldades, modo bandeira e abertura automática à volta dos números.": "Расчисти поле, не наступив на мину. Три уровня сложности, режим флажков и автоматическое открытие вокруг цифр. Расчисти поле, не наступив на мину. Три уровня сложности, режим флажков и автоматическое открытие вокруг цифр.",
"Todos os jogos do telemóvel num sítio só, com os teus recordes e o último que jogaste. Todos os jogos do telemóvel num sítio só, com os teus recordes e o último que jogaste.": "Все игры телефона в одном месте, с твоими рекордами и последней сыгранной игрой. Все игры телефона в одном месте, с твоими рекордами и последней сыгранной игрой.",
"Assistente com IA: dúvidas sobre o servidor e o telemóvel, contas, tempo e mais. Assistente com IA: dúvidas sobre o servidor e o telemóvel, contas, tempo e mais.": "ИИ-ассистент: вопросы о сервере и телефоне, расчёты, погода и многое другое. ИИ-ассистент: вопросы о сервере и телефоне, расчёты, погода и многое другое.",
"Vê onde estão a família e os amigos que partilham a localização contigo, e partilha a tua. Vê onde estão a família e os amigos que partilham a localização contigo, e partilha a tua.": "Смотри, где находятся семья и друзья, которые делятся с тобой геопозицией, и делись своей. Смотри, где находятся семья и друзья, которые делятся с тобой геопозицией, и делись своей.",
"Recebe e paga faturas de empresas e do estado. Paga ou recusa num toque.": "Получай и оплачивай счета от компаний и государства. Оплати или отклони одним касанием.",
"O que se passa em Los Santos, em 280 caracteres. Segue a cidade em tempo real.": "Что происходит в Los Santos, в 280 символах. Следи за городом в реальном времени.",
"Restaurantes, mercearia e farmácia entregues onde estiveres. Segue o teu estafeta no mapa em tempo real. Restaurantes, mercearia e farmácia entregues onde estiveres. Segue o teu estafeta no mapa em tempo real.": "Рестораны, продукты и аптека с доставкой куда угодно. Следи за курьером на карте в реальном времени. Рестораны, продукты и аптека с доставкой куда угодно. Следи за курьером на карте в реальном времени.",
